class TaskBinding {
record Plane(String id,String kind,int seats,double payload,int range,int fuel){}
static Plane view(company.model.Aircraft p){return new Plane(p.getId(),p.kind(),p.getSeats(),p.getPayloadTonnes(),p.getRangeKm(),p.getFuelLitresPerHour());}
static Object fixture(){return new company.model.Airline(java.util.List.of(new company.model.PassengerPlane("1",150,12,3000,2400),new company.model.CargoPlane("2",2,20,4500,3000),new company.model.PassengerPlane("3",80,6,1800,1500)));}
static long capacity(Object a){return ((company.model.Airline)a).capacity();}static double payload(Object a){return ((company.model.Airline)a).payload();}static java.util.List<Plane> planes(Object a){return ((company.model.Airline)a).planes().stream().map(TaskBinding::view).toList();}static java.util.List<Plane> sorted(Object a){return ((company.model.Airline)a).byRange().stream().map(TaskBinding::view).toList();}static java.util.List<Plane> find(Object a,int lo,int hi){return ((company.model.Airline)a).matchingFuel(lo,hi).stream().map(TaskBinding::view).toList();}static void save(Object a,java.nio.file.Path p)throws Exception{company.persistence.AirlineConnector.save(p,(company.model.Airline)a);}static Object load(java.nio.file.Path p)throws Exception{return company.persistence.AirlineConnector.load(p);}static void update(java.nio.file.Path p,int seats)throws Exception{company.persistence.AirlineConnector.changeSeats(p,"3",seats);}static void setTransient(Object a,int value){((company.model.Airline)a).setMenuCount(value);}static int transientValue(Object a){return ((company.model.Airline)a).getMenuCount();}static void setGlobal(String s){company.model.Airline.setGlobalLabel(s);}static String global(){return company.model.Airline.getGlobalLabel();}static String expectedGlobal(String before,String current){return current;}static int expectedTransient(int value){return 0;}
}
